local resource=assert(GameInfo.Resources.RESOURCE_ANTIQUITY_SITE).Index
local owner=Game.GetLocalPlayer()
local visited=Game:GetProperty("JAC_ARTIFACT_VISITED_SITES") or {}
local found
for index=0,Map.GetPlotCount()-1 do local q=Map.GetPlotByIndex(index)
 local units=q and Map.GetUnitsAt(q)
 if q and q:GetResourceType()==resource and (q:GetOwner()==owner or q:GetOwner()==-1) and not q:IsWater()
   and not q:IsImpassable() and (not units or units:GetCount()==0)
   and not visited[tostring(index)] and Game.GetArtifactAtPlot(index) then found=q;break end
end
assert(found,'no unoccupied local-or-neutral genuine land antiquity site')
ExposedMembers.JAC_ArtifactSite={X=found:GetX(),Y=found:GetY(),Plot=found:GetIndex()}
return 'genuine extraction site selected with existing artifact record'

